package app.cadence;

import android.app.*;
import android.content.res.ColorStateList;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.widget.*;

public final class EqualizerPanel {
    private final Activity activity;private final AudioEqualizer equalizer;private final ThemePalette palette;
    private final Handler handler=new Handler(Looper.getMainLooper());
    private Dialog dialog;private TextView status,preset,preampValue,balanceValue;private SeekBar preamp,balance;private Switch headroom;private Curve curve;
    private final SeekBar[] sliders=new SeekBar[5];private final TextView[] gains=new TextView[5];
    public EqualizerPanel(Activity activity,AudioEqualizer equalizer){this.activity=activity;this.equalizer=equalizer;palette=ThemePalette.current(activity);}
    public void show(){
        LinearLayout page=column();page.setPadding(dp(22),dp(12),dp(22),dp(20));page.setBackground(palette.card(activity,palette.surface(),20));
        Switch enabled=new Switch(activity);enabled.setText("Equalizer enabled");enabled.setTextColor(palette.foreground());enabled.setChecked(equalizer.enabled());enabled.setOnCheckedChangeListener((v,on)->{equalizer.setEnabled(on);updateStatus();});page.addView(enabled,new LinearLayout.LayoutParams(-1,dp(52)));
        status=text(12);page.addView(status);preset=text(16);preset.setPadding(0,dp(14),0,dp(4));page.addView(preset);curve=new Curve();page.addView(curve,new LinearLayout.LayoutParams(-1,dp(84)));
        HorizontalScrollView rail=new HorizontalScrollView(activity);rail.setHorizontalScrollBarEnabled(false);LinearLayout presets=new LinearLayout(activity);
        for(int i=0;i<AudioEqualizer.PRESETS.length;i++){final int index=i;Button button=new Button(activity);button.setAllCaps(false);button.setTextSize(12);button.setText(AudioEqualizer.PRESETS[i]);button.setOnClickListener(v->{equalizer.preset(index);refresh();});presets.addView(button);}rail.addView(presets);page.addView(rail);
        for(int i=0;i<5;i++){final int index=i;TextView label=text(12);int hz=AudioEqualizer.FREQUENCIES[i];label.setText(hz>=1000?String.format(java.util.Locale.ROOT,"%.1f kHz",hz/1000f):hz+" Hz");page.addView(label);LinearLayout row=row();sliders[i]=slider(2400,"Equalizer "+hz+" Hz");row.addView(sliders[i],new LinearLayout.LayoutParams(0,dp(42),1));gains[i]=text(12);row.addView(gains[i],new LinearLayout.LayoutParams(dp(64),-2));page.addView(row);sliders[i].setOnSeekBarChangeListener(change((value,user)->{gains[index].setText(db(value-1200));if(user){equalizer.setBand(index,value-1200);updateStatus();}}));}
        TextView advanced=text(17);advanced.setText("Fine tune");advanced.setPadding(0,dp(16),0,dp(12));page.addView(advanced);
        TextView preampTitle=text(13);preampTitle.setText("Preamp · output attenuation");page.addView(preampTitle);LinearLayout gainRow=row();preamp=slider(1200,"Preamp attenuation");gainRow.addView(preamp,new LinearLayout.LayoutParams(0,dp(46),1));preampValue=text(12);gainRow.addView(preampValue,new LinearLayout.LayoutParams(dp(64),-2));page.addView(gainRow);preamp.setOnSeekBarChangeListener(change((value,user)->{preampValue.setText(db(value-1200));if(user){equalizer.setPreamp(value-1200);updateStatus();}}));
        TextView balanceTitle=text(13);balanceTitle.setText("Stereo balance · left / right");page.addView(balanceTitle);LinearLayout balanceRow=row();balance=slider(200,"Stereo balance");balanceRow.addView(balance,new LinearLayout.LayoutParams(0,dp(46),1));balanceValue=text(12);balanceRow.addView(balanceValue,new LinearLayout.LayoutParams(dp(64),-2));page.addView(balanceRow);balance.setOnSeekBarChangeListener(change((value,user)->{int b=value-100;balanceValue.setText(b==0?"Center":(b<0?"L ":"R ")+Math.abs(b)+"%");if(user)equalizer.setBalance(b);}));
        headroom=new Switch(activity);headroom.setText("Auto headroom");headroom.setTextSize(14);headroom.setTextColor(palette.foreground());headroom.setOnCheckedChangeListener((v,on)->{equalizer.setHeadroom(on);updateStatus();});page.addView(headroom,new LinearLayout.LayoutParams(-1,dp(48)));TextView help=text(11);help.setText("Reduces player gain for boosted tone bands. Balance applies to stereo PCM. The master toggle bypasses all sound adjustments.");page.addView(help);
        LinearLayout saved=row();Button save=new Button(activity);save.setAllCaps(false);save.setText("Save as preset");save.setOnClickListener(v->savePreset());saved.addView(save,new LinearLayout.LayoutParams(0,-2,1));Button load=new Button(activity);load.setAllCaps(false);load.setText("Saved presets");load.setOnClickListener(v->savedPresets(false));saved.addView(load,new LinearLayout.LayoutParams(0,-2,1));page.addView(saved);
        Button reset=new Button(activity);reset.setAllCaps(false);reset.setText("Reset sound settings");reset.setOnClickListener(v->{equalizer.reset();refresh();});page.addView(reset);TextView note=text(11);note.setText("Tone-band support and gain limits depend on the audio output. Settings and custom presets stay on this device.");page.addView(note);
        ScrollView scroll=new ScrollView(activity);scroll.addView(page);dialog=new AlertDialog.Builder(activity).setTitle("MuseDock sound studio").setView(scroll).setPositiveButton("Done",null).create();dialog.setOnDismissListener(d->handler.removeCallbacksAndMessages(null));dialog.show();refresh();handler.post(new Runnable(){public void run(){if(!dialog.isShowing())return;updateStatus();handler.postDelayed(this,700);}});
    }
    private interface Change{void set(int value,boolean user);}
    private SeekBar.OnSeekBarChangeListener change(Change change){return new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int value,boolean user){change.set(value,user);}};}
    private void savePreset(){EditText name=new EditText(activity);name.setSingleLine();name.setHint("Name your sound");name.setTextColor(palette.foreground());name.setPadding(dp(22),dp(16),dp(22),dp(16));AlertDialog form=new AlertDialog.Builder(activity).setTitle("Save custom preset").setView(name).setPositiveButton("Save",null).setNegativeButton("Cancel",null).create();form.show();form.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String title=name.getText().toString().trim();if(title.isEmpty()||title.length()>30){name.setError("Use 1–30 characters");return;}Runnable save=()->{try{equalizer.saveCustom(title);form.dismiss();refresh();}catch(IllegalArgumentException error){name.setError(error.getMessage());}};if(equalizer.customPresets().contains(title))new AlertDialog.Builder(activity).setTitle("Replace saved preset?").setMessage(title).setPositiveButton("Replace",(d,w)->save.run()).setNegativeButton("Keep",null).show();else save.run();});}
    private void savedPresets(boolean deleting){java.util.List<String> names=equalizer.customPresets();if(names.isEmpty()){Toast.makeText(activity,"Save your first custom preset",Toast.LENGTH_SHORT).show();return;}AlertDialog.Builder menu=new AlertDialog.Builder(activity).setTitle(deleting?"Delete preset":"Your saved sounds").setItems(names.toArray(new String[0]),(d,index)->{if(deleting)equalizer.deleteCustom(names.get(index));else equalizer.loadCustom(names.get(index));refresh();}).setNegativeButton("Close",null);if(!deleting)menu.setNeutralButton("Delete a preset",(d,w)->savedPresets(true));menu.show();}
    public void dismiss(){if(dialog!=null)dialog.dismiss();}
    private void refresh(){int[] values=equalizer.levels();for(int i=0;i<5;i++){sliders[i].setProgress(values[i]+1200);gains[i].setText(db(values[i]));}preamp.setProgress(equalizer.preamp()+1200);preampValue.setText(db(equalizer.preamp()));balance.setProgress(equalizer.balance()+100);balanceValue.setText(equalizer.balance()==0?"Center":(equalizer.balance()<0?"L ":"R ")+Math.abs(equalizer.balance())+"%");headroom.setChecked(equalizer.headroom());updateStatus();}
    private void updateStatus(){status.setText(equalizer.status());preset.setText("Curve · "+equalizer.preset());if(curve!=null)curve.invalidate();}
    private String db(int value){return String.format(java.util.Locale.ROOT,"%+.1f dB",value/100f);}
    private SeekBar slider(int max,String description){SeekBar view=new SeekBar(activity);view.setMax(max);view.setProgressTintList(ColorStateList.valueOf(palette.accent()));view.setThumbTintList(ColorStateList.valueOf(palette.accent()));view.setContentDescription(description);return view;}
    private TextView text(int size){TextView v=new TextView(activity);v.setTextSize(size);v.setTextColor(palette.foreground());return v;}
    private LinearLayout column(){LinearLayout v=new LinearLayout(activity);v.setOrientation(LinearLayout.VERTICAL);return v;}
    private LinearLayout row(){LinearLayout v=new LinearLayout(activity);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
    private int dp(int size){return Math.round(size*activity.getResources().getDisplayMetrics().density);}
    private final class Curve extends View{private final Paint paint=new Paint(3);Curve(){super(activity);setContentDescription("Current five-band equalizer curve");}@Override protected void onDraw(Canvas canvas){int[] values=equalizer.levels();float width=getWidth()-dp(20),height=getHeight()-dp(20);paint.setColor(palette.outline());paint.setStrokeWidth(dp(1));for(int i=0;i<3;i++)canvas.drawLine(dp(10),dp(10)+i*height/2,getWidth()-dp(10),dp(10)+i*height/2,paint);paint.setColor(palette.accent());paint.setStrokeWidth(dp(2));for(int i=0;i<5;i++){float x=dp(10)+width*i/4,y=dp(10)+height*(1200-values[i])/2400;if(i>0){float previous=dp(10)+height*(1200-values[i-1])/2400;canvas.drawLine(dp(10)+width*(i-1)/4,previous,x,y,paint);}canvas.drawCircle(x,y,dp(3),paint);}}}
}
